      { letra: 'B', texto: 'Síndrome de Down e Edwards.', explicacao: 'Incorreta. Down (47, XX ou XY) e Edwards (47, XX ou XY) são ambas trissomias.' },
      { letra: 'C', texto: 'Síndrome de Turner e Down.', explicacao: 'Incorreta. A ordem está invertida: Turner (45, X0) é monossomia e Down (47) é trissomia.' },
      { letra: 'D', texto: 'Síndrome de Edwards e Turner.', explicacao: 'Correta! Edwards (47, XX ou XY) é uma síndrome por adição (trissomia) e Turner (45, X0) é uma síndrome por subtração (monossomia).' }
